def add_actions(w,root):
    import csv,json
    a=json.loads((root/'action/action_results.json').read_text(encoding='utf8'))
    b=json.loads((root/'action_text/action_results.json').read_text(encoding='utf8'))
    w.page('Исполнение  /  Память кодового агента','Что передавать из прошлой сессии','На 34 задачах сравнили две формы передачи одних и тех же разговоров. В обеих версиях решатель получил одинаковые исходные файлы, описание задачи и две найденные сессии.')
    w.p('В публичном agent-memory-bench прошлые сессии записаны при расследовании специально подготовленных инцидентов. В корпусе 196 сессий, 1 220 поисковых окон. Авторский BM25 ищет по тексту задачи. Контроль выдаёт наиболее подходящий сырой фрагмент каждой из двух сессий. Новый вариант при записи сессии сохраняет последнее сообщение пользователя, названия реально вызванных инструментов и окончание последнего содержательного сообщения агента. Ограничение одинаково — до 150 слов из каждой сессии.')
    w.p('Третье условие показывает исходный уровень решателя без памяти. Во всех трёх условиях локальная Qwen3-8B генерирует программу, которая изменяет чистую рабочую копию. Затем отдельный процесс запускает официальный проверяющий модуль и скрытые от решателя тестовые данные. Для 34 задач все 34 правильных эталона прошли тесты, все 34 заведомо неполных решения и все 34 исходные копии провалились. Проверка изоляции также прошла.')
    w.tbl(['Одинаково в трёх условиях','Что менялось'],[['Весовая версия Qwen3-8B, BF16, RTX 3090','Содержимое секции памяти'],['Однократный ответ, жадное декодирование, лимит 1 280 выходных токенов','В отдельном повторе форма передачи программы'],['Каждая из 34 задач, исходный Git-снимок и исполняемый тест','Порядок вычисления задан хешем задания и условия']],[9,8.1],True)
    w.p('Одно задание (ts-bool-env) координатор видел при настройке проверяющего процесса. Изоляция исключала этот контекст из входа модели. При исключении задания основная разница первого опыта остаётся +1 успешная задача, второго −1. Сырые окна участвовали в поиске в обоих условиях. По этим данным нельзя оценить экономию хранения исходного индекса.')
    w.source('Корпус, программные задачи и официальный тестовый стенд', 'https://github.com/GiulioDER/agent-memory-bench/tree/c1b15726f1153b02dda0490ca1936bb86a809514')
    w.source('Публичная ревизия локального решателя Qwen3-8B', 'https://huggingface.co/Qwen/Qwen3-8B/tree/b968826d9c46dd6066d109eabc6255188de91218')
    w.page('Исполнение  /  204 сгенерированных решения','Пройденные тесты и стоимость контекста','В повторе с выдачей чистого Python исходные фрагменты дали 5 успешных задач, карточки — 4, пустой контекст — 3. На уровне конкретных задач карточки уступили исходным фрагментам один раз и ни разу их не превзошли.')
    def row(folder,k,name):
        return [name,*(str(folder['arms'][x][k])+'/34' for x in ['empty','raw','receipt'])]
    w.tbl(['Показатель','Без памяти','Фрагмент','Карточка'],[row(a,'successes','Основной опыт, JSON'),row(b,'successes','Повтор, Python'),['Исполнилось без ошибки, JSON','16/34','5/34','8/34'],['Исполнилось без ошибки, Python','26/34','27/34','27/34'],['Входные токены, повтор','16 325','34 400','28 871'],['Средняя длина памяти, слов','0','293,8','239,4']],[7.2,3.3,3.3,3.3],True)
    w.p('В основном опыте 57 из 102 ответов дословно скопировали заполнитель из примера JSON. В первом сравнении карточки с фрагментами получились один выигрыш и ноль потерь, p = 1. После первых признаков сбоя зафиксировали повтор на всех задачах. Убрали пример JSON и попросили чистый Python. Общее число программ, закончивших исполнение без ошибки, выросло с 29 до 80 из 102. Основной опыт сохранён целиком.')
    w.p('В повторе единственной потерей карточки относительно фрагментов стала задача ts-mig-name, точный парный p = 1. Относительно пустого контекста карточка добавила ts-schema-additive. Экономия составила 5 529 токенов на 34 входах, или 16,1% полного объёма запросов с фрагментами. Для расчёта относительно одной добавки памяти вычитают общий вход без памяти. По этой шкале экономия составила 30,6%.')
    w.p('Исходный поиск нашёл полный комплект предусмотренных предшествующих сессий лишь для 16 из 34 задач. Условия измеряют одновременно применимость извлечённого опыта и способность читателя его использовать. Два режима вывода повторяют те же задачи и веса. Число независимых пар при сравнении качества равно 34.')
    w.page('Исполнение  /  Приложение к результатам','Все парные исходы для 34 задач','Каждая тройка показывает результаты в порядке «без памяти / исходный фрагмент / карточка». Единица означает, что решение прошло исполняемую проверку. Слева от названия режима приведён основной опыт, справа — повтор с чистым Python.')
    def tabledata(path):
        with path.open(encoding='utf8',newline='') as fp:return {r['task']:' '.join('1' if r[x]=='True' else '0' for x in ('empty','raw','receipt')) for r in csv.DictReader(fp)}
    u=tabledata(root/'action/action_per_task.csv');v=tabledata(root/'action_text/action_per_task.csv');tasks=sorted(u);half=len(tasks)//2
    def entry(key):return [key,u[key],v[key]]
    w.tbl(['Задача','JSON','Python','Задача','JSON','Python'],[entry(task)+entry(tasks[j+half]) for j,task in enumerate(tasks[:half])],[4.2,1.9,2.3,4.3,2.0,2.4],True)
    w.p('Публичный основной эксперимент авторов использует другой решатель, их агентную интеграцию и несколько состояний истории, включая устаревшие и противоречивые записи. В нашем опыте проверена базовая история с присутствующими сведениями. Для сравнения с продуктовой таблицей авторов необходим их режим работы.')
    w.source('Официальное описание охвата и ограничений agent-memory-bench', 'https://github.com/GiulioDER/agent-memory-bench/blob/c1b15726f1153b02dda0490ca1936bb86a809514/README.md')

